def _default = logic.param('default').getReal()
def _content = _default.get('content')

if(_content != null){

    // 去除空白字符减少误判
    def trimmed = _content.trim()
    
    // HTML 特征检查
    boolean hasHtmlTags = trimmed =~ /<(?i)(html|head|body|div|p|a|img|table|ul|ol|li)[\s>]/
    boolean hasHtmlDoctype = trimmed =~ /<!DOCTYPE\s+html/i
    boolean hasHtmlComments = trimmed =~ /<!--.*?-->/
    boolean hasHtmlSelfClosing = trimmed =~ /<(br|hr|img|input|meta|link)[\s>]/i
    
    // Markdown 特征检查
    boolean hasMdHeaders = trimmed =~ /^#{1,6}\s+\w/
    boolean hasMdLinks = trimmed =~ /\[.*?\]\(.*?\)/
    boolean hasMdImages = trimmed =~ /!\[.*?\]\(.*?\)/
    boolean hasMdLists = trimmed =~ /^(\s*[-*+]\s+|\s*\d+\.\s+)/
    boolean hasMdCodeBlocks = trimmed =~ /```[\s\S]*?```|~~~[\s\S]*?~~~/
    boolean hasMdBlockquotes = trimmed =~ /^>\s+/
    boolean hasMdHorizontalRule = trimmed =~ /^(\s*[*_-]\s*){3,}/
    
    // 计算特征数量
    def htmlFeatures = [hasHtmlTags, hasHtmlDoctype, hasHtmlComments, hasHtmlSelfClosing].count { it }
    def mdFeatures = [hasMdHeaders, hasMdLinks, hasMdImages, hasMdLists, hasMdCodeBlocks, hasMdBlockquotes, hasMdHorizontalRule].count { it }
    
    println "HTML 特征数: $htmlFeatures, MD 特征数: $mdFeatures"
    
    if (mdFeatures > htmlFeatures) {
         _default.set('format_type', "MD")
    } else {
         _default.set('format_type', "HTML")
    }

}
